-- Active staff by branch, job and nationality (headcount base for turnover rates). One text column LN = branch|job|nationality code|n. About 115 rows at Al Faihaa.
SELECT (CASE WHEN t.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(t.ORG,3,1) ELSE SUBSTR(NVL(t.ORG,'??'),1,2) END)||'|'||REPLACE(NVL(j.DESCRIPTION,'?'),CHR(10),'')||'|'||NVL(TO_CHAR(m.NATIONALITY_CODE),'?')||'|'||COUNT(*) LN FROM {P}PS_STAFF_CONTRACT c JOIN {P}STAFF_MASTER m ON m.STAFF_ID=c.STAFF_ID LEFT JOIN (SELECT STAFF_ID, MAX(ORGANIZATION_NO) ORG, MAX(STAFF_JOB_ID) JB FROM {P}PS_STAFF_INTERNAL_TRANSFERS WHERE CURRENT_JOB='Y' GROUP BY STAFF_ID) t ON t.STAFF_ID=c.STAFF_ID LEFT JOIN (SELECT USER_CODE, MAX(DESCRIPTION) DESCRIPTION FROM {P}CODES_MASTER WHERE CODE_TYPE=250 GROUP BY USER_CODE) j ON j.USER_CODE=t.JB WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y' GROUP BY (CASE WHEN t.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(t.ORG,3,1) ELSE SUBSTR(NVL(t.ORG,'??'),1,2) END), NVL(j.DESCRIPTION,'?'), NVL(TO_CHAR(m.NATIONALITY_CODE),'?') ORDER BY 1
